import{_ as r,o,c as a,a2 as n}from"./chunks/framework.CYjxsSA2.js";const c=JSON.parse('{"title":"关于 VAELOR","description":"","frontmatter":{},"headers":[],"relativePath":"intro.md","filePath":"intro.md"}'),e={name:"intro.md"};function l(s,t,i,d,g,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="关于-vaelor" tabindex="-1">关于 VAELOR <a class="header-anchor" href="#关于-vaelor" aria-label="Permalink to &quot;关于 VAELOR&quot;">​</a></h1><p><strong>VAELOR</strong> 是一款面向授权渗透测试与攻防演练的<strong>红队全链路平台</strong> —— 桌面应用，单机运行，由 <strong>Gh0xE9</strong> 开发与维护。</p><p>它把资产发现、站点分析、自动化渗透与漏洞管理放在同一个应用里：数据按项目隔离，各模块结果互相引用，最终由<strong>军团智能体</strong>对目标发起多轮自动化作业，把验证过的发现沉淀进漏洞账本。</p><p>当前版本：<strong>DXE-1.0.0</strong>。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>军团智能体</strong> —— 一句话下达任务，自动拆解为子任务并行推进，回收结论直到任务完成</li><li><strong>可控的自动化</strong> —— 计划模式（先出计划再动手）、三档权限强制拦截、高危操作人工确认、命令可强制隔离执行</li><li><strong>资产测绘</strong> —— 空间扫描、空间测绘（FOFA / Quake / Hunter / Shodan）、漏洞测绘三者结果统一入库</li><li><strong>漏洞管理</strong> —— 发现直读账本、按严重度分诊；侦察报告按资产归集并可导出</li><li><strong>云上综合</strong> —— 拿到 AK/SK 后枚举与利用公有云存储、云平台与 API 资产</li><li><strong>桌面助手</strong> —— 常驻的小助手，一句话管项目、下发扫描、查阅漏洞</li><li><strong>三语界面</strong> —— 简体中文 / English / 한국어</li></ul><h2 id="界面结构" tabindex="-1">界面结构 <a class="header-anchor" href="#界面结构" aria-label="Permalink to &quot;界面结构&quot;">​</a></h2><p>进入项目后，左侧是 <strong>7 个执行面板</strong>：</p><table tabindex="0"><thead><tr><th>面板</th><th>用途</th></tr></thead><tbody><tr><td><strong>仪表盘</strong></td><td>项目概览、资产与漏洞统计、模型用量、活动流</td></tr><tr><td><strong>军团</strong></td><td>自动化渗透的主体工作区</td></tr><tr><td><strong>漏洞管理</strong></td><td>发现分诊与侦察报告</td></tr><tr><td><strong>漏洞测绘</strong></td><td>站点爬虫、指纹、敏感信息、目录扫描、智渗透</td></tr><tr><td><strong>云上综合</strong></td><td>公有云开放平台利用</td></tr><tr><td><strong>空间扫描</strong></td><td>端口扫描与服务识别</td></tr><tr><td><strong>空间测绘</strong></td><td>测绘平台查询与入库</td></tr></tbody></table><p>不在项目内时，左侧另有 <strong>首页</strong>、<strong>军团总览</strong>（跨项目会话看板），底部是 <strong>系统配置</strong> 与 <strong>关于</strong>。</p><h2 id="数据与运行" tabindex="-1">数据与运行 <a class="header-anchor" href="#数据与运行" aria-label="Permalink to &quot;数据与运行&quot;">​</a></h2><ul><li>所有数据保存在本地数据目录（项目、配置、证据、导出结果），<strong>不需要账号、不需要联网激活</strong></li><li>数据目录位置见<a href="/vaelor/download.html#数据目录">下载与安装</a>，需要时可改到别处</li></ul><h2 id="开始阅读" tabindex="-1">开始阅读 <a class="header-anchor" href="#开始阅读" aria-label="Permalink to &quot;开始阅读&quot;">​</a></h2><ul><li><a href="/vaelor/download.html">下载与安装</a> — 运行环境、数据目录与可选资源</li><li><a href="/vaelor/quickstart.html">快速上手</a> — 十分钟跑通第一个项目</li><li><a href="/vaelor/guide/project.html">项目管理</a> — 项目、目标资产与仪表盘</li><li><a href="/vaelor/guide/army.html">军团智能体</a> — 核心工作区：计划、权限、隔离与模型配置</li><li><a href="/vaelor/guide/vulnreports.html">漏洞管理</a> — 分诊口径与报告导出</li></ul>',14)])])}const p=r(e,[["render",l]]);export{c as __pageData,p as default};
